#include <stdio.h>

void swap(int *a, int *b) {  // a, b হলো অ্যাড্রেস
  int temp = *a;
  *a = *b;   // *a = a এর অ্যাড্রেসে যে ভ্যালু, তা পরিবর্তন
  *b = temp;
}

int main() {
  int x = 5, y = 10;
  printf("Before: x=%d, y=%d\n", x, y);
  swap(&x, &y);  // অ্যাড্রেস পাঠানো হচ্ছে
  printf("After: x=%d, y=%d\n", x, y);
  return 0;
}

