#include <stdio.h>

int binarySearch(int arr[], int n, int key) {
  int low = 0, high = n - 1;

  while (low <= high) {
    int mid = (low + high) / 2;
    if (arr[mid] == key) return mid;  // পেয়ে গেলে ইনডেক্স রিটার্ন
    if (arr[mid] < key) low = mid + 1; // ডান দিকে
    else high = mid - 1;              // বাম দিকে
  }
  return -1;  // পাওয়া যায়নি
}

int main() {
  int arr[] = {10, 20, 30, 40, 50};
  int n = 5, key = 30;

  int pos = binarySearch(arr, n, key);
  if (pos != -1) {
    printf("%d found at index %d\n", key, pos);
  } else {
    printf("%d not found.\n", key);
  }
  return 0;
}

#include <stdio.h>

void bubbleSort(int arr[], int n) {
  for (int i = 0; i < n-1; i++) {
    for (int j = 0; j < n-1-i; j++) {
      if (arr[j] > arr[j+1]) {
        // swap
        int temp = arr[j];
        arr[j] = arr[j+1];
        arr[j+1] = temp;
      }
    }
  }
}

int main() {
  int arr[] = {64, 34, 25, 12, 22};
  int n = 5;

  bubbleSort(arr, n);

  printf("Sorted: ");
  for (int i = 0; i < n; i++) {
    printf("%d ", arr[i]);
  }
  printf("\n");
  return 0;
}

#include <stdio.h>

int main() {
  char op;
  float a, b, result;
  char again;

  do {
    printf("\n--- Simple Calculator ---\n");
    printf("Enter operation (+, -, *, /): ");
    scanf(" %c", &op);  // %c এর আগে স্পেস দিন — আগের \n ইগনোর করবে

    printf("Enter two numbers: ");
    scanf("%f %f", &a, &b);

    switch (op) {
      case '+': result = a + b; break;
      case '-': result = a - b; break;
      case '*': result = a * b; break;
      case '/': 
        if (b == 0) {
          printf("Error: Division by zero!\n");
          continue;  // এই ইটারেশন স্কিপ
        }
        result = a / b;
        break;
      default:
        printf("Invalid operator!\n");
        continue;
    }

    printf("%.2f %c %.2f = %.2f\n", a, op, b, result);

    printf("Calculate again? (y/n): ");
    scanf(" %c", &again);
  } while (again == 'y' || again == 'Y');

  printf("Thanks for using!\n");
  return 0;
}

